718	            throw new Failure(Messages.AbstractItem_BeingDeleted(getPronoun()));
719	        }
720	        try {
721	            // if a build is in progress. Cancel it.
722	            if (responsibleForAbortingBuilds || ownsRegistration) {
723	                Queue queue = Queue.getInstance();
724	                if (this instanceof Queue.Task) {
725	                    // clear any items in the queue so they do not get picked up
726	                    queue.cancel((Queue.Task) this);
727	                }
728	                // now cancel any child items - this happens after ItemDeletion registration, so we can use a snapshot
729	                for (Queue.Item i : queue.getItems()) {
730	                    Item item = Tasks.getItemOf(i.task);
731	                    while (item != null) {
732	                        if (item == this) {
733	                            if (!queue.cancel(i)) {
734	                                LOGGER.warning(() -> "failed to cancel " + i);
735	                            }
736	                            break;
737	                        }
738	                        if (item.getParent() instanceof Item) {
739	                            item = (Item) item.getParent();
740	                        } else {
741	                            break;
742	                        }
743	                    }
744	                }
745	                // interrupt any builds in progress (and this should be a recursive test so that folders do not pay
746	                // the 15 second delay for every child item). This happens after queue cancellation, so will be
747	                // a complete set of builds in flight
748	                Map<Executor, Queue.Executable> buildsInProgress = new LinkedHashMap<>();
749	                for (Computer c : Jenkins.get().getComputers()) {
750	                    for (Executor e : c.getAllExecutors()) {
751	                        final WorkUnit workUnit = e.getCurrentWorkUnit();
752	                        final Queue.Executable executable = workUnit != null ? workUnit.getExecutable() : null;
753	                        final SubTask subtask = executable != null ? getParentOf(executable) : null;
754	
755	                        if (subtask != null) {
756	                            Item item = Tasks.getItemOf(subtask);
757	                            while (item != null) {
758	                                if (item == this) {
759	                                    buildsInProgress.put(e, e.getCurrentExecutable());
760	                                    e.interrupt(Result.ABORTED);
761	                                    break;
762	                                }
763	                                if (item.getParent() instanceof Item) {
764	                                    item = (Item) item.getParent();
765	                                } else {
766	                                    break;
767	                                }
768	                            }
769	                        }
770	                    }
771	                }
772	                if (!buildsInProgress.isEmpty()) {
773	                    // give them 15 seconds or so to respond to the interrupt
774	                    long expiration = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
775	                    // comparison with executor.getCurrentExecutable() == computation currently should always be true
776	                    // as we no longer recycle Executors, but safer to future-proof in case we ever revisit recycling
777	                    while (!buildsInProgress.isEmpty() && expiration - System.nanoTime() > 0L) {
778	                        // we know that ItemDeletion will prevent any new builds in the queue
779	                        // ItemDeletion happens-before Queue.cancel so we know that the Queue will stay clear
780	                        // Queue.cancel happens-before collecting the buildsInProgress list
781	                        // thus buildsInProgress contains the complete set we need to interrupt and wait for
782	                        for (Iterator<Map.Entry<Executor, Queue.Executable>> iterator =
783	                             buildsInProgress.entrySet().iterator();
784	                             iterator.hasNext(); ) {
785	                            Map.Entry<Executor, Queue.Executable> entry = iterator.next();
786	                            // comparison with executor.getCurrentExecutable() == executable currently should always be
787	                            // true as we no longer recycle Executors, but safer to future-proof in case we ever
788	                            // revisit recycling.
789	                            if (!entry.getKey().isAlive()
790	                                    || entry.getValue() != entry.getKey().getCurrentExecutable()) {
791	                                iterator.remove();
792	                            }
793	                            // I don't know why, but we have to keep interrupting
794	                            entry.getKey().interrupt(Result.ABORTED);
795	                        }
796	                        Thread.sleep(50L);
797	                    }
798	                    if (!buildsInProgress.isEmpty()) {
799	                        throw new Failure(Messages.AbstractItem_FailureToStopBuilds(
800	                                buildsInProgress.size(), getFullDisplayName()
801	                        ));
802	                    }
803	                }
804	            }
805	            if (this instanceof ItemGroup) {
806	                // delete individual items first
807	                // (disregard whether they would be deletable in isolation)
808	                // JENKINS-34939: do not hold the monitor on this folder while deleting them
809	                // (thus we cannot do this inside performDelete)
810	                try (ACLContext oldContext = ACL.as2(ACL.SYSTEM2)) {
811	                    for (Item i : ((ItemGroup<?>) this).getItems(TopLevelItem.class::isInstance)) {
812	                        try {
813	                            i.delete();
814	                        } catch (AbortException e) {
815	                            throw (AbortException) new AbortException(
816	                                    "Failed to delete " + i.getFullDisplayName() + " : " + e.getMessage()).initCause(e);
817	                        } catch (IOException e) {
818	                            throw new IOException("Failed to delete " + i.getFullDisplayName(), e);
819	                        }
820	                    }
821	                }
822	            }
823	            synchronized (this) { // could just make performDelete synchronized but overriders might not honor that
824	                performDelete();
825	            } // JENKINS-19446: leave synch block, but JENKINS-22001: still notify synchronously
826	        } finally {
827	            if (ownsRegistration) {
828	                ItemDeletion.deregister(this);
829	            }
830	        }
831	        getParent().onDeleted(AbstractItem.this);
832	        Jenkins.get().rebuildDependencyGraphAsync();
833	    }

