186	     * @since 2.51
187	     */
188	    public static void checkBeforeCopy(final Item src, final ItemGroup parent) throws Failure {
189	        for (ItemListener l : all()) {
190	            try {
191	                l.onCheckCopy(src, parent);
192	            } catch (Failure e) {
193	                throw e;
194	            } catch (RuntimeException x) {
195	                LOGGER.log(Level.WARNING, "failed to send event to listener of " + l.getClass(), x);
196	            }
197	        }
198	    }
