213	    /**
214	     * Calls {@link #onRenamed} and {@link #onLocationChanged} as appropriate.
215	     * @param rootItem the topmost item whose location has just changed
216	     * @param oldFullName the previous {@link Item#getFullName}
217	     * @since 1.548
218	     */
219	    public static void fireLocationChange(final Item rootItem, final String oldFullName) {
220	        String prefix = rootItem.getParent().getFullName();
221	        if (!prefix.isEmpty()) {
222	            prefix += '/';
223	        }
224	        final String newFullName = rootItem.getFullName();
225	        assert newFullName.startsWith(prefix);
226	        int prefixS = prefix.length();
227	        if (oldFullName.startsWith(prefix) && oldFullName.indexOf('/', prefixS) == -1) {
228	            final String oldName = oldFullName.substring(prefixS);
229	            final String newName = rootItem.getName();
230	            assert newName.equals(newFullName.substring(prefixS));
231	            Listeners.notify(ItemListener.class, false, l -> l.onRenamed(rootItem, oldName, newName));
232	        }
233	        Listeners.notify(ItemListener.class, false, l -> l.onLocationChanged(rootItem, oldFullName, newFullName));
234	        if (rootItem instanceof ItemGroup) {
235	            for (final Item child : Items.allItems2(ACL.SYSTEM2, (ItemGroup) rootItem, Item.class)) {
236	                final String childNew = child.getFullName();
237	                assert childNew.startsWith(newFullName);
238	                assert childNew.charAt(newFullName.length()) == '/';
239	                final String childOld = oldFullName + childNew.substring(newFullName.length());
240	                Listeners.notify(ItemListener.class, false, l -> l.onLocationChanged(child, childOld, childNew));
241	            }
242	        }
243	    }
